<?php require '../config/database.php';admin_required();if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare('INSERT INTO rifas(titulo,descricao,imagem,preco,total_numeros,tipo,status,data_sorteio) VALUES(?,?,?,?,?,?,?,NULLIF(?,\'\'))');$s->execute([$_POST['titulo'],$_POST['descricao'],$_POST['imagem'],$_POST['preco'],$_POST['total_numeros'],$_POST['tipo'],'ativa',$_POST['data_sorteio']]);redirect('/admin/rifas.php');}$rifas=$pdo->query('SELECT * FROM rifas ORDER BY id DESC')->fetchAll();?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/css/style.css"><title>Rifas</title></head><body><header class="top"><div class="wrap"><a href="index.php">← Painel</a></div></header><main class="wrap"><div class="box"><h2>Nova rifa</h2><form method="post"><input name="titulo" placeholder="Título" required><textarea name="descricao" placeholder="Descrição"></textarea><input name="imagem" placeholder="URL da imagem"><input type="number" step="0.01" min="0.01" name="preco" placeholder="Preço" required><input type="number" min="1" name="total_numeros" value="100" required><select name="tipo"><option value="selecionavel">Selecionável</option><option value="aleatoria">Aleatória</option></select><input type="datetime-local" name="data_sorteio"><button class="btn">Criar rifa</button></form></div><div class="box"><h2>Rifas</h2><table><tr><th>ID</th><th>Título</th><th>Tipo</th><th>Preço</th><th>Status</th></tr><?php foreach($rifas as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['titulo'])?></td><td><?=e($r['tipo'])?></td><td>R$ <?=number_format($r['preco'],2,',','.')?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table></div></main></body></html>
